create or replace function public.pantavion_can_view_social_post(p_post_id uuid, p_viewer uuid default auth.uid()) returns boolean language sql stable security definer set search_path=public,pg_temp as $$ select exists(select 1 from public.social_posts p where p.id=p_post_id and p.deleted_at is null and (p.author_id=p_viewer or p.visibility='public' or (p.visibility='connections' and p_viewer is not null and public.pantavion_are_connections(p.author_id,p_viewer)))) $$; revoke all on function public.pantavion_can_view_social_post(uuid,uuid) from public,anon,authenticated; create table if not exists public.social_post_media(id uuid primary key default gen_random_uuid(),post_id uuid not null references public.social_posts(id) on delete cascade,owner_id uuid not null references auth.users(id) on delete cascade,storage_path text,personal_media_id uuid references public.personal_media(id) on delete restrict,media_kind text not null check(media_kind in('photo','video','audio','file')),mime_type text,created_at timestamptz not null default now(),check(personal_media_id is not null or storage_path is not null)); create index if not exists social_post_media_post_idx on public.social_post_media(post_id); create unique index if not exists social_post_media_unique_personal_item_idx on public.social_post_media(post_id,personal_media_id) where personal_media_id is not null; alter table public.social_post_media enable row level security; create policy social_media_select_visible on public.social_post_media for select to authenticated using(public.pantavion_can_view_social_post(post_id)); create policy social_media_insert_own on public.social_post_media for insert to authenticated with check(owner_id=auth.uid() and exists(select 1 from public.social_posts p where p.id=post_id and p.author_id=auth.uid() and p.deleted_at is null) and (personal_media_id is null or exists(select 1 from public.personal_media m where m.id=personal_media_id and m.owner_id=auth.uid()))); create policy social_media_delete_own on public.social_post_media for delete to authenticated using(owner_id=auth.uid()); grant select,insert,delete on public.social_post_media to authenticated; revoke all on public.social_post_media from anon; alter table public.social_posts alter column body drop not null; alter table public.social_posts drop constraint if exists social_posts_body_check; alter table public.social_comments add column if not exists parent_comment_id uuid references public.social_comments(id) on delete cascade; alter table public.social_comments add column if not exists edited_at timestamptz;